mapper.select:
select l.id, l.user_id, p.student_no, u.nick_name as student_name, l.transfer_type, l.from_id, l.from_name, l.to_id, l.to_name, l.term_id, l.operator_id, op.nick_name as operator_name, l.operate_time, l.remark from edu_transfer_log l left join sys_user u on u.user_id = l.user_id left join edu_user_profile p on p.user_id = l.user_id left join sys_user op on op.user_id = l.operator_id
and l.user_id = #{userId} and l.transfer_type = #{transferType} and l.term_id = #{termId}
order by l.operate_time desc
